import { useEffect } from "react";
import { useNavigate } from "react-router-dom";

/**
 * Redirects to "/zugriffsfehler" if localStorage does not contain `${levelKey}` === "true"
 * @param {string} levelKey e.g. "level1Passed", "level2Passed"
 */
export default function useLevelGuard(levelKey) {
  const navigate = useNavigate();

  useEffect(() => {
    const passed = localStorage.getItem(levelKey);
    if (passed !== "true") {
      navigate("/zugriffsfehler");
    }
  }, [navigate, levelKey]);
}
